/**
 * Validation logic for the Book action
 */
import type { ServiceSelection } from '../booking.js';
import type { FormValues } from '@wix/forms/components';
/**
 * Parameters for canBook validation
 */
export interface CanBookParams {
    serviceSelections: ServiceSelection[];
    formSubmission: FormValues | null;
}
/**
 * Validates if booking can be executed
 * Checks that all required data is present:
 * - At least one service selection
 * - Each service selection has either a `timeSlot` or a non-empty
 *   `rangeTimeSlots` (DAY-range path)
 * - Form submission filled
 *
 * @param params - The booking data to validate
 * @returns true if booking can proceed, false otherwise
 */
export declare function canBook(params: CanBookParams): boolean;
